import{_ as o,o as t,c as a,a2 as d}from"./chunks/framework.BDCokyix.js";const h=JSON.parse('{"title":"Naming Policy","description":"","frontmatter":{},"headers":[],"relativePath":"naming-policy.md","filePath":"naming-policy.md","lastUpdated":1780254295000}'),n={name:"naming-policy.md"};function c(r,e,i,s,l,p){return t(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="naming-policy" tabindex="-1">Naming Policy <a class="header-anchor" href="#naming-policy" aria-label="Permalink to &quot;Naming Policy&quot;">​</a></h1><p>This document defines the canonical terminology for the Soma codebase. All new docs, code, and contracts should use these terms.</p><p><strong>Last Updated:</strong> 2026-03-20</p><hr><h2 id="core-concepts" tabindex="-1">Core Concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core Concepts&quot;">​</a></h2><h3 id="space" tabindex="-1">Space <a class="header-anchor" href="#space" aria-label="Permalink to &quot;Space&quot;">​</a></h3><p>A <strong>space</strong> is the primary unit of collaboration. It contains documents, members, and resources.</p><p><strong>Use:</strong></p><ul><li><code>space</code> (noun) in docs, code, UI</li><li><code>space_id</code> for identifiers</li><li><code>SpaceId</code> in proto/types</li></ul><p><strong>Do NOT use:</strong></p><ul><li><code>class</code> (historical term from earlier versions)</li><li><code>room</code> (confuses with chat room concept)</li></ul><p><strong>Examples:</strong></p><ul><li><code>ListSpaces</code> (RPC)</li><li><code>space_members</code> (table)</li><li><code>/spaces/:spaceId</code> (route)</li></ul><hr><h3 id="document" tabindex="-1">Document <a class="header-anchor" href="#document" aria-label="Permalink to &quot;Document&quot;">​</a></h3><p>A <strong>document</strong> is collaborative content within a space. Documents are edited collaboratively and may reference blobs.</p><p><strong>Use:</strong></p><ul><li><code>document</code> (noun) in docs, code, UI</li><li><code>document_id</code> for identifiers</li><li><code>DocumentId</code> in proto/types</li></ul><p><strong>Do NOT use:</strong></p><ul><li><code>page</code> when referring to the content itself (pages are navigation metadata)</li><li><code>Yoopta document</code> (internal implementation detail)</li></ul><p><strong>Examples:</strong></p><ul><li><code>UpsertDocument</code> (RPC)</li><li><code>documents</code> (table)</li><li><code>DocumentEditor</code> (component)</li></ul><hr><h3 id="cache-peer" tabindex="-1">Cache Peer <a class="header-anchor" href="#cache-peer" aria-label="Permalink to &quot;Cache Peer&quot;">​</a></h3><p>A <strong>cache peer</strong> is a libp2p peer that fetches and caches blobs addressed by content ID. Cache peers never accept user uploads and are not a source of truth.</p><p><strong>Use:</strong></p><ul><li><code>cache peer</code> in docs and external communication</li><li><code>cache_peer</code> in code when the concept is external-facing</li></ul><p><strong>Internal code may use:</strong></p><ul><li><code>VDF</code> as an internal acronym (from &quot;Verified Data Fetcher&quot;)</li><li><code>soma-vdfs</code> as the crate name (historical, to be renamed later)</li></ul><p><strong>Do NOT use:</strong></p><ul><li><code>VDFS</code> (inconsistent with VDF acronym)</li><li><code>cache bot</code> (confuses with general-purpose bots)</li></ul><p><strong>Migration path:</strong></p><ul><li>Crate <code>soma-vdfs</code> → <code>soma-blobs</code> (Phase 6)</li><li>Doc <code>blobs-vdfs.md</code> → <code>blobs-cache-peers.md</code> (Phase 2)</li></ul><hr><h3 id="admin-mode" tabindex="-1">Admin Mode <a class="header-anchor" href="#admin-mode" aria-label="Permalink to &quot;Admin Mode&quot;">​</a></h3><p><strong>Admin mode</strong> is the operating mode of <code>somad bot</code> that exposes administrative HTTP endpoints for join decisions, issuer delegation, and space management.</p><p><strong>Use:</strong></p><ul><li><code>admin</code> as the mode name</li><li><code>--mode admin</code> in CLI</li><li><code>SOMA_MODE=admin</code> in environment</li></ul><p><strong>Do NOT use:</strong></p><ul><li><code>server-daemon</code> (confuses with desktop daemon)</li></ul><hr><h2 id="event-naming" tabindex="-1">Event Naming <a class="header-anchor" href="#event-naming" aria-label="Permalink to &quot;Event Naming&quot;">​</a></h2><p>Events should follow the pattern: <code>&lt;entity&gt;_&lt;action&gt;</code></p><p><strong>Current:</strong></p><ul><li><code>YooptaBlobAddedEvent</code> → <strong>Transitional</strong> (alias added in Phase 5)</li><li><code>yoopta_blob_added</code> → <strong>Transitional</strong> (alias added in Phase 5)</li></ul><p><strong>Target:</strong></p><ul><li><code>DocumentBlobAddedEvent</code> → <strong>Implemented</strong> (Phase 5)</li><li><code>document_blob_added</code> → <strong>Implemented</strong> (Phase 5)</li></ul><p><strong>Migration:</strong></p><ul><li>✅ Add new names as aliases (Phase 5 - COMPLETE)</li><li>Remove old names (Phase 6)</li></ul><hr><h2 id="proto-package-naming" tabindex="-1">Proto Package Naming <a class="header-anchor" href="#proto-package-naming" aria-label="Permalink to &quot;Proto Package Naming&quot;">​</a></h2><p><strong>Current:</strong></p><ul><li><code>space.v1</code> → <strong>Implemented</strong> (Phase 6)</li></ul><p><strong>Migration:</strong></p><hr><h2 id="binary-crate-naming" tabindex="-1">Binary / Crate Naming <a class="header-anchor" href="#binary-crate-naming" aria-label="Permalink to &quot;Binary / Crate Naming&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>Kind</th><th>Purpose</th><th>Notes</th></tr></thead><tbody><tr><td><code>somad</code></td><td>Binary</td><td>Unified server binary with <code>bot</code> / <code>relay</code> / <code>rendezvous</code> / <code>bff</code> / <code>all</code> subcommands</td><td>Stable; replaces the former per-service <code>soma-botd</code> / <code>soma-relayd</code> / <code>soma-rendezvousd</code> / <code>soma-bffd</code> / <code>soma-serverd</code> binaries</td></tr><tr><td><code>soma-daemon</code></td><td>Library</td><td>Desktop peer / daemon runtime</td><td>Stable; embedded by the Tauri host (<code>desktop-daemon</code>), no standalone binary</td></tr><tr><td><code>soma-agentd</code></td><td>Library</td><td>Desktop agent runtime (Yjs drift resolver, etc.)</td><td>Stable; embedded by the Tauri host (<code>desktop-agent</code>), no standalone binary</td></tr></tbody></table><hr><h2 id="directory-naming" tabindex="-1">Directory Naming <a class="header-anchor" href="#directory-naming" aria-label="Permalink to &quot;Directory Naming&quot;">​</a></h2><h3 id="desktop-workspace" tabindex="-1">Desktop Workspace <a class="header-anchor" href="#desktop-workspace" aria-label="Permalink to &quot;Desktop Workspace&quot;">​</a></h3><p><strong>Target (completed):</strong></p><ul><li><code>desktop/desktop-ui</code></li><li><code>desktop/desktop-config</code></li><li><code>desktop/desktop-editor</code></li><li><code>desktop/desktop-icons</code></li></ul><p>(The Electron-era <code>desktop/desktop-proto</code> (<code>@soma/proto</code>) and <code>desktop/desktop-data</code> (<code>@soma/desktop-db</code>) packages, along with the <code>backend/crates/soma-node</code> (<code>@soma/node</code>) napi addon, were removed with the Electron app. The current desktop app is the Tauri V2 shell at <code>desktop/desktop-app</code>.)</p><hr><h2 id="historical-terms-do-not-revive" tabindex="-1">Historical Terms (Do Not Revive) <a class="header-anchor" href="#historical-terms-do-not-revive" aria-label="Permalink to &quot;Historical Terms (Do Not Revive)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Term</th><th>Origin</th><th>Why Deprecated</th></tr></thead><tbody><tr><td><code>class</code></td><td>Early classroom focus</td><td><code>space</code> is broader</td></tr><tr><td><code>Yoopta</code></td><td>Editor library</td><td>Implementation detail</td></tr><tr><td><code>VDFS</code></td><td>Inconsistent acronym</td><td>Use VDF or cache peer</td></tr><tr><td><code>server-daemon</code></td><td>Confusing</td><td>Use admin mode</td></tr><tr><td><code>spaceroom</code></td><td>Proto package</td><td>Renamed to space.v1 (Phase 6)</td></tr><tr><td><code>electron</code></td><td>Previous desktop framework</td><td>Use Tauri V2 / <code>desktop/desktop-app</code></td></tr></tbody></table><hr><h2 id="implementation-checklist" tabindex="-1">Implementation Checklist <a class="header-anchor" href="#implementation-checklist" aria-label="Permalink to &quot;Implementation Checklist&quot;">​</a></h2><p>When adding new code/docs:</p><ul><li>[ ] Uses <code>space</code> not <code>class</code></li><li>[ ] Uses <code>document</code> for collaborative content</li><li>[ ] Uses <code>cache peer</code> in external-facing docs</li><li>[ ] Uses <code>admin</code> for bot admin mode</li><li>[ ] Avoids historical framework names (tauri, etc.)</li><li>[ ] Events follow <code>&lt;entity&gt;_&lt;action&gt;</code> pattern</li></ul>',70)])])}const u=o(n,[["render",c]]);export{h as __pageData,u as default};
